import { Component } from '@angular/core';
import { Flight } from 'src/app/models/flight.model';
import { FlightsService } from 'src/app/services/flights.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-flight-search',
  templateUrl: './search.component.html',
  styleUrls: ['./search.component.scss']
})
export class FlightSearchComponent {
  depart: string = '';
  destination: string = '';
  dataOra: string = '';
  loading = false;
  errorMessage = '';

  directFlights: Flight[] = [];
  layoverConnections: any[] = [];
  selectedSeat: { [key: string]: string } = {}; // id volo -> numero posto

  constructor(
    private flightService: FlightsService,
    private router: Router
  ) {}

  search() {
    this.loading = true;
    this.errorMessage = '';
    this.directFlights = [];
    this.layoverConnections = [];

    this.flightService.searchFlights(this.depart, this.destination, this.dataOra)
      .subscribe({
        next: (res) => {
          this.directFlights = res.directFlights;
          this.layoverConnections = res.layoverConnections;
          this.loading = false;
        },
        error: (err) => {
          this.errorMessage = err.error?.message || 'Errore durante la ricerca.';
          this.loading = false;
        }
      });
  }

  acquistaVolo(flight: Flight) {
    const seat = this.selectedSeat[flight._id];
    if (!seat) {
      alert('Seleziona un posto prima di acquistare.');
      return;
    }
    this.router.navigate(['/checkout'], { state: { flightId: flight._id, seat } });
  }

  acquistaEntrambiVoli(conn: any) {
    const seat1 = this.selectedSeat[conn.firstLeg._id];
    const seat2 = this.selectedSeat[conn.secondLeg._id];
    if (!seat1 || !seat2) {
      alert('Seleziona entrambi i posti prima di acquistare.');
      return;
    }
    this.router.navigate(['/checkout'], {
      state: {
        firstFlightId: conn.firstLeg._id,
        firstSeat: seat1,
        secondFlightId: conn.secondLeg._id,
        secondSeat: seat2
      }
    });
  }
}
